const ODOO = { url: ($env.ODOO_URL || 'http://odoo:8069') + '/jsonrpc', db: $env.ODOO_DB || 'hdx',
  login: $env.ODOO_N8N_LOGIN || 'n8n', pw: $env.ODOO_N8N_PASSWORD || '' };
if (!ODOO.pw) throw new Error('Thiếu ODOO_N8N_PASSWORD trong .env');
// Gọi JSON-RPC của Odoo, ném lỗi kèm thông báo của Odoo
const rpc = async (service, method, args) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: ODOO.url, json: true, timeout: 30000,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } } });
  if (r.error) throw new Error(`Odoo: ${(r.error.data && r.error.data.message) || r.error.message}`);
  return r.result;
};
const uid = await rpc('common', 'login', [ODOO.db, ODOO.login, ODOO.pw]);
if (!uid) throw new Error('Odoo: sai ODOO_N8N_LOGIN hoặc ODOO_N8N_PASSWORD');
// Gọi một method của model Odoo
const call = (model, method, args, kw = {}) => rpc('object', 'execute_kw', [ODOO.db, uid, ODOO.pw, model, method, args, kw]);

const j = $input.first().json;
const byName = j.odoo_sale_order && /^S\d+/.test(String(j.odoo_sale_order));
const dom = byName ? [['name', '=', String(j.odoo_sale_order)]] : [['client_order_ref', '=', String(j.tiktok_order_id || '')]];
const so = (await call('sale.order', 'search_read', [dom], { fields: ['name'], limit: 1 }))[0];
if (!so) return [{ json: { tiktok_order_id: j.tiktok_order_id, skipped: 'Odoo không có Sales Order cho đơn này' } }];
const NHOM = { dang_giao: 'Đang giao', da_giao: 'Đã giao', giao_that_bai: 'Giao thất bại: theo dõi hàng hoàn về kho', khac: 'Cập nhật giao hàng' };
let body;
if (j.action === 'ghi_van_don') {
  body = `Đã đặt vận chuyển${j.picking ? ' cho phiếu ' + j.picking : ''}. Mã vận đơn: ${j.tracking_number || 'chưa có'}.`
    + (j.label_url ? ` Phiếu gửi hàng: ${j.label_url}` : '');
} else if (j.action === 'cap_nhat_trang_thai') {
  body = `${NHOM[j.nhom] || NHOM.khac} (${j.status || '?'}). Mã vận đơn: ${j.tracking_number || 'chưa có'}.`;
} else {
  throw new Error(`action không hợp lệ: ${j.action}`);
}
await call('sale.order', 'message_post', [[so.id]], { body, message_type: 'comment', subtype_xmlid: 'mail.mt_note' });
return [{ json: { tiktok_order_id: j.tiktok_order_id, odoo_sale_order: so.name, ghi: body } }];
